metric scenario_revenue = order_items | sum(order_items.quantity * products.scenario_price);
explore {
  dimensions { category: products.category }
  measures { total_revenue: revenue, scenario_revenue: scenario_revenue, uplift: scenario_revenue - revenue }
  sorts { total_revenue desc }
}

28-retention.aql:
dimension customers.first_order_at = orders | min(orders.ordered_at) | dimensionalize(customers.id);
dimension orders.months_since_first = date_diff('month', customers.first_order_at, orders.ordered_at);
metric active_customers = orders | count_distinct(orders.customer_id);
explore {
  dimensions {
    cohort: customers.first_order_at | month(),
    month_n: orders.months_since_first,
  }
  measures {
    active: active_customers,
    retention: active_customers * 1.0 / (active_customers | exclude_grains(orders.months_since_first)),
  }
  sorts { cohort asc, month_n asc }
}

29-funnel.aql:
dimension customers.order_n = orders | count(orders.id) | dimensionalize(customers.id);
dimension customers.completed_n = orders | count(orders.id) | where(orders.status == 'completed') | dimensionalize(customers.id);
explore {
  dimensions { country: customers.country }
  measures {
    signed_up: customers | count(customers.id),
    ordered: customers | count(customers.id) | where(customers.order_n > 0),
    completed: customers | count(customers.id) | where(customers.completed_n > 0),
    repeat_buyer: customers | count(customers.id) | where(customers.completed_n > 1),
  }
  sorts { signed_up desc }
}

